func hookWritesCheckpointData(eventType agent.EventType, claudePostTodoCheckpointHook bool) bool {
	if claudePostTodoCheckpointHook {
		return true
	}
	return eventType == agent.TurnEnd || eventType == agent.SubagentEnd
}

